import{_ as r}from"./chunks/flights-route.DhfUIE4N.js";import{_ as a,C as s,o as d,c as l,a3 as o,j as n,E as i}from"./chunks/framework.B9qR_F1m.js";const u="/bilder/flights-funk.jpg",M=JSON.parse('{"title":"Flights","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/flights.md","filePath":"bereiche/flights.md"}'),g={name:"bereiche/flights.md"},h={class:"tiles"},c={class:"tile",href:"./beladung"},p={class:"tile-icon"},m={class:"tile",href:"./dtc"},b={class:"tile-icon"},k={class:"tile",href:"./angriff"},f={class:"tile-icon"},S={class:"tile",href:"./lineup-card"},A={class:"tile-icon"};function z(T,e,C,w,F,D){const t=s("Icon");return d(),l("div",null,[e[8]||(e[8]=o('<h1 id="flights" tabindex="-1">Flights <a class="header-anchor" href="#flights" aria-label="Permalink to &quot;Flights&quot;">​</a></h1><p>Hier planst du einen Flight im Detail. Links wählst du den Flight, oben im Panel die Reiter:</p><p><a href="#auftrag-tanker-und-awacs">Auftrag</a> (nur Tanker und AWACS) · <strong>Route</strong> · <strong>Units &amp; Funk</strong> · <a href="./beladung">Beladung</a> · <a href="./dtc">DTC</a> · <a href="./angriff">Angriff</a> · <a href="./lineup-card">Lineup Card</a></p><p>Den Reiter <strong>DTC</strong> gibt es nur für F-16C und F/A-18C, <strong>Angriff</strong> und <strong>Lineup Card</strong> nur für spielbare Flights.</p><p><img src="'+r+'" alt="Flight mit Route auf der Karte und Steerpoint-Tabelle" loading="lazy"></p><p>Über den Reitern steht der Kopf des Flights: Name, Anzahl und Typ, Aufgabe, Frequenz und der DCS-Gruppenname mit DCS-Callsign. Als Mission Designer hast du dort außerdem <strong>Duplizieren</strong>: eine Kopie der Gruppe mit neuen Namen, IDs, Link-16-STN und Bordnummern; Route, Beladung, Funk, Callsign und TACAN bleiben gleich, etwa für eine Ablösung auf demselben Track. Beim gemeinsamen Planen auf dem Server geht das nur bei Gruppen, die in Shardwing angelegt wurden.</p><h2 id="route" tabindex="-1">Route <a class="header-anchor" href="#route" aria-label="Permalink to &quot;Route&quot;">​</a></h2><h3 id="quelle-fur-route-lineup-card-und-karten" tabindex="-1">Quelle für Route, Lineup Card und Karten <a class="header-anchor" href="#quelle-fur-route-lineup-card-und-karten" aria-label="Permalink to &quot;Quelle für Route, Lineup Card und Karten&quot;">​</a></h3><p>Ein Flight kann zwei Routen haben: den <strong>Flugplan der Mission</strong> (die Wegpunkte aus dem Mission Editor) und die <strong>Steerpoints einer Cartridge</strong>. Oben wählst du, welche gilt:</p><ul><li><strong>Automatisch</strong> – hat der Flight eine Cartridge mit Steerpoints, gilt sie, sonst der Flugplan.</li><li><strong>Flugplan der Mission (MIZ)</strong> – immer die Missionsroute.</li><li><strong>DTC „…“</strong> – eine bestimmte Cartridge.</li></ul><p>Grüne Schilder rechts bestätigen, woher Route und Funk gerade kommen (z. B. <em>Route aus DTC „F-16C-SA-2-ATTACK“</em>). Timing, Deconfliction und Kneeboard-Karten nutzen dieselbe Quelle.</p><h3 id="die-tabelle" tabindex="-1">Die Tabelle <a class="header-anchor" href="#die-tabelle" aria-label="Permalink to &quot;Die Tabelle&quot;">​</a></h3><p>Bei der Missionsroute siehst du pro Wegpunkt Name, Typ, Koordinate, <strong>Höhe</strong>, <strong>Geschwindigkeit (GS)</strong> und <strong>ETA</strong>. Name, Höhe und Geschwindigkeit sind direkt änderbar; die Zeiten rechnet Shardwing daraus neu – so, wie DCS die Route fliegt. Eine fest eingetragene Zeit sperrt den Punkt wie ETA-Lock im Mission Editor.</p><div class="tip custom-block"><p class="custom-block-title">Zeiten passen nicht?</p><p>Passen die Zeiten im Mission Editor nicht zu den Geschwindigkeiten (typisch bei kopierten Routen), sagt Shardwing es oben in Orange. Sobald du etwas änderst, rechnet es alle Zeiten sauber neu.</p></div><h3 id="auf-der-karte-bearbeiten" tabindex="-1">Auf der Karte bearbeiten <a class="header-anchor" href="#auf-der-karte-bearbeiten" aria-label="Permalink to &quot;Auf der Karte bearbeiten&quot;">​</a></h3><p>Als Designer kannst du die Missionsroute (auch von KI-Flights) direkt auf der Karte ändern: Punkte <strong>ziehen</strong>, mit <strong>+</strong> zwischen zwei Punkten einfügen, mit <strong>Rechtsklick</strong> löschen. Kommt die Route aus einer Cartridge, bearbeitest du sie im <a href="./dtc">DTC-Editor</a>.</p><h2 id="units-funk" tabindex="-1">Units &amp; Funk <a class="header-anchor" href="#units-funk" aria-label="Permalink to &quot;Units &amp; Funk&quot;">​</a></h2><p><img src="'+u+'" alt="Reiter Units &amp; Funk" loading="lazy"></p><p><strong>Gruppenfrequenz</strong> – die Frequenz des Flights in MHz, AM oder FM. Jeder Flight sollte eine eigene haben, damit sich die Flights nicht gegenseitig hören; Shardwing weist auf doppelte Frequenzen, Frequenzen außerhalb des Kanalrasters und Frequenzen eines Netzes im <a href="./kneeboards#comm-plan">Comm Plan</a> hin. <strong>Frequenzen verteilen</strong> gibt jedem Spieler-Flight mit doppelter oder fehlender Frequenz die nächste freie im selben Band; vorher zeigt Shardwing, was sich ändert. Nur der Designer ändert die Gruppenfrequenz. Shardwing schreibt sie beim Speichern in die Mission (mit eingeschaltetem Funk); was danach im Mission Editor geändert wird, bleibt. Tanker und AWACS stellst du unter <a href="#auftrag-tanker-und-awacs">Auftrag</a> ein.</p><p><strong>Units</strong> – jedes Flugzeug des Flights mit:</p><table tabindex="0"><thead><tr><th>Spalte</th><th>Inhalt</th></tr></thead><tbody><tr><td>Callsign</td><td>Eigener Callsign aus der <a href="./uebersicht#callsigns-aufgaben">Übersicht</a>, sonst DCS-Gruppenname</td></tr><tr><td>DCS-Callsign</td><td>z. B. Enfield 1-1</td></tr><tr><td>Tail</td><td>Bordnummer</td></tr><tr><td>Laser</td><td>Laser-Code</td></tr><tr><td>Skill</td><td>Client, Player oder KI-Stufe</td></tr><tr><td>DTC</td><td>Welche Cartridge dieses Flugzeug lädt, mit AutoLoad</td></tr></tbody></table><p><strong>Funk-Presets laut Mission</strong> – die Kanäle aus dem Mission Editor für Radio 1 und 2. Hat der Flight eine Cartridge mit COMM-Bereich, gilt im Jet deren Belegung; die bearbeitest du im <a href="./dtc#comm">DTC</a> oder paketweit im <a href="./kneeboards#comm-plan">Comm Plan</a>.</p><h2 id="tanker-awacs-und-flights-anlegen" tabindex="-1">Tanker, AWACS und Flights anlegen <a class="header-anchor" href="#tanker-awacs-und-flights-anlegen" aria-label="Permalink to &quot;Tanker, AWACS und Flights anlegen&quot;">​</a></h2><p>Als Mission Designer legst du Tanker, AWACS und F-16C- oder F/A-18C-Flights direkt in Shardwing an: links über der Flight-Liste <strong>+ Anlegen</strong>, dann <strong>Tanker</strong>, <strong>AWACS</strong> oder <strong>Flight</strong>. Im Panel wählst du nur:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Typ</td><td>Tanker: KC-135 (Boom), KC-135 MPRS und S-3B (Drogue). AWACS: E-3A, E-2C, A-50.</td></tr><tr><td>Seite und Land</td><td>Blau oder Rot und ein Land, das in der Mission schon Einheiten hat. Hat eine Seite noch gar keine Einheiten, bietet Shardwing CJTF Blue oder USA (Blau) bzw. CJTF Red oder Russia (Rot) an und legt das Land beim Speichern mit an.</td></tr><tr><td>Start</td><td><strong>In der Luft</strong>: Du klickst danach auf die Karte, dort beginnt die Gruppe. <strong>Kalt</strong> oder <strong>Heiß vom Parkplatz</strong> und <strong>Von der Startbahn</strong>: Flugplatz in der Liste wählen (der nächste zum Bullseye steht oben) oder auf der Karte anklicken. Tanker und AWACS landen am Ende wieder dort. Der Platz muss der Seite gehören, das prüft Shardwing nicht.</td></tr><tr><td>Nur Flight</td><td>Anzahl (Single bis 4-Ship), <strong>Spieler</strong> (Client-Slots) oder <strong>KI</strong>, Aufgabe für DCS (CAP, SEAD, CAS, Bodenangriff, Escort) und das DCS-Callsign (Enfield, Springfield, Uzi …)</td></tr></tbody></table><p>Callsign, Frequenz und TACAN füllt Shardwing mit freien Werten vor (z. B. Shell 1, wenn Texaco und Arco schon fliegen; TACAN ab 51Y). Danach landest du im Reiter <strong>Auftrag</strong>, und Track zeichnen ist gleich eingeschaltet: Anker setzen, dann das Ende des Inbound-Legs. Alles Weitere stellst du dort ein wie bei jedem Tanker oder AWACS.</p><p>Beim Start vom Parkplatz sucht Shardwing freie Plätze nebeneinander, auf die der Typ passt, und zeigt sie auf der Karte blau. Ein neuer Flight bekommt leere Stationen und vollen Innentank, freie STN und eine eigene Frequenz. Danach landest du im Reiter <strong>Route</strong>, die Karte zoomt auf den Platz: Mit dem <strong>+</strong> hinter dem Startpunkt hängst du die Wegpunkte an. Beladung, Funk, eigenes Callsign und Aufgabe fürs Briefing stellst du ein wie bei jedem Flight.</p><h3 id="start-und-parkplatze" tabindex="-1">Start und Parkplätze <a class="header-anchor" href="#start-und-parkplatze" aria-label="Permalink to &quot;Start und Parkplätze&quot;">​</a></h3><p>Startet ein Flight auf einem Flugplatz, steht über seiner Route, wie er startet: <strong>Kalt</strong> oder <strong>Heiß vom Parkplatz</strong> oder <strong>Von der Startbahn</strong>, und bei Parkplätzen der Platz jeder Maschine. Als Mission Designer änderst du das hier:</p><ul><li><strong>Platz</strong> pro Maschine aus der Liste. Belegte Plätze (mit dem Flight dahinter) und zu kleine sind markiert.</li><li><strong>Automatisch</strong> – freie, passende Plätze nebeneinander für den ganzen Flight.</li><li><strong>Auf der Karte wählen</strong> – nacheinander pro Maschine einen Platz anklicken. Auf der Karte sind freie Plätze grün, belegte grau, zu kleine blass und die eigenen blau mit Nummer.</li></ul><p>Ein Klick auf einen Parkplatz der Karte öffnet seine Karte: Größe, Shelter, wer dort steht. Als Mission Designer setzt du von dort eine Maschine des gewählten Flights hin (steht ein Flight-Kamerad schon dort, tauschen die beiden); einen belegten Platz öffnet <strong>… öffnen</strong> den Flight, der dort steht. Beim Anlegen setzt ein Klick auf einen Platz den Lead dorthin, die anderen kommen daneben.</p><p>Doppelt belegte oder zu kleine Plätze meldet Shardwing darunter, ändert aber nichts von selbst. Den Flugplatz selbst wechselst du hier nicht, nur beim Anlegen. Beim Speichern schreibt Shardwing Startart und Plätze in die Mission; was danach jemand im Mission Editor ändert, bleibt.</p><p>Neue Gruppen tragen in der Liste und im Kopf das Zeichen <strong>neu</strong>, bis du speicherst; dann schreibt Shardwing sie in die Mission, vor allen anderen Änderungen. Bis dahin entfernst du sie mit <strong>Entfernen</strong> im Kopf, samt Auftrag, Route und Funk.</p><h2 id="auftrag-tanker-und-awacs" tabindex="-1">Auftrag (Tanker und AWACS) <a class="header-anchor" href="#auftrag-tanker-und-awacs" aria-label="Permalink to &quot;Auftrag (Tanker und AWACS)&quot;">​</a></h2><p>Tanker und AWACS der Mission, die von der KI geflogen werden, haben vorne den Reiter <strong>Auftrag</strong>. In der Liste stehen sie in jeder Seite oben. Damit du die aus der Mission siehst, nimm links den Haken bei <strong>nur spielbare</strong> heraus; in Shardwing angelegte stehen immer drin. Als Mission Designer stellst du hier ein:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Callsign</td><td>DCS-Callsign aus der festen Liste (Tanker: Texaco, Arco, Shell …; AWACS: Overlord, Magic, Wizard …) und Flight-Nummer. Gilt für alle Flugzeuge der Gruppe.</td></tr><tr><td>Frequenz</td><td>Gruppenfrequenz in MHz, AM oder FM</td></tr><tr><td>TACAN</td><td>nur Tanker: Kanal, X/Y, Kennung (bis drei Zeichen), Peilung senden. Für Tanker ist Y üblich.</td></tr></tbody></table><p>Shardwing schreibt Callsign, Funk und TACAN beim Speichern in die Mission: Callsign der Flugzeuge, Gruppenfrequenz (mit eingeschaltetem Funk) und das TACAN am ersten Wegpunkt, so wie der Mission Editor es anlegt. Ändert jemand danach im Mission Editor dieselben Werte, bleiben die stehen.</p><h3 id="track" tabindex="-1">Track <a class="header-anchor" href="#track" aria-label="Permalink to &quot;Track&quot;">​</a></h3><p>Unter <strong>Track</strong> legst du fest, wo der Tanker oder AWACS kreist. Der Track ist eine ganz normale Zeichnung (AR-Track beim Tanker, AWACS-Orbit beim AWACS), die mit der Gruppe verknüpft ist:</p><ul><li><strong>Track zeichnen</strong> – Anker setzen, dann Richtung und Länge klicken.</li><li><strong>Zeichnung übernehmen …</strong> – einen AR-Track, CAP oder AWACS-Orbit, den du schon gezeichnet hast. Sein Name (z. B. MAIN) bleibt, das Callsign kommt in den Zusatz.</li><li><strong>Orbit aus der Mission übernehmen</strong> – hat die Gruppe im Mission Editor schon einen Orbit, wird er zur Zeichnung.</li></ul><p>Danach gilt: Verschiebst oder drehst du die Zeichnung (hier oder unter <a href="./zeichnungen">Zeichnungen</a>), zieht der Orbit mit. Die Beschriftung zeigt Callsign, Flugfläche, Frequenz und TACAN und folgt jeder Änderung im Auftrag.</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td>Race-Track / Kreis</td><td>Race-Track fliegt die KI zwischen zwei Wegpunkten hin und her, beim Kreis um den Anker.</td></tr><tr><td>Inbound-Kurs, Leg (NM)</td><td>Kurs und Länge des Tank-Legs von P1 nach P2. P1 (Beginn des Legs) bleibt beim Ändern liegen.</td></tr><tr><td>Seite tauschen</td><td>Legt das Oval auf die andere Seite der Achse. Die KI kurvt in DCS immer links herum; Shardwing lässt sie dafür am anderen Ende beginnen.</td></tr><tr><td>Höhe (FL), KIAS</td><td>Höhe und angezeigte Geschwindigkeit im Orbit. DCS will die wahre Geschwindigkeit (TAS); Shardwing rechnet um und zeigt sie daneben.</td></tr></tbody></table><p>Die Breite des Ovals stellt die KI selbst ein (aus der Geschwindigkeit). Shardwing zeichnet sie ungefähr so, wie MOOSE es tut, z. B. etwa 12 NM bei 300 KIAS in FL250.</p><p>Beim Speichern schreibt Shardwing den Orbit in die Route der Gruppe: Hat sie schon einen Orbit, wandern dessen Wegpunkte; sonst kommen zwei neue Wegpunkte dazu (vor einer Landung). Alle anderen Wegpunkte und Aufgaben bleiben.</p><h3 id="route-zum-track-und-zuruck" tabindex="-1">Route zum Track und zurück <a class="header-anchor" href="#route-zum-track-und-zuruck" aria-label="Permalink to &quot;Route zum Track und zurück&quot;">​</a></h3><p>Ohne eigene Wegpunkte fliegt der Tanker direkt vom Start zum Track. Führt das durch gegnerische SAM-Ringe, baust du eine Entry- und eine Exit-Route:</p><ul><li>Auf der Karte setzt <strong>+</strong> zwischen Start und Track einen Entry-Wegpunkt, <strong>+</strong> hinter dem Track einen Exit-Wegpunkt – wie bei jeder KI-Route. Die beiden Wegpunkte des Tracks (P1, P2) kommen aus der Zeichnung und lassen sich dort nicht ziehen.</li><li><strong>Landung</strong> hängt eine Landung an einem Platz an (nur Plätze mit Piste, die nächsten zuerst, der Startplatz oben). Nach dem Orbit fliegt die KI die Exit-Route und landet dort.</li><li>Verschiebst du später den Track, bleiben Entry- und Exit-Wegpunkte, wo sie sind.</li></ul><p>Der Kasten zeigt, wie viele Entry- und Exit-Wegpunkte es gibt.</p><p>Darunter stehen kleine Hinweise, nichts davon ist eine Sperre: TACAN-Kanal doppelt vergeben, Kanal X wie eine Bodenstation der Karte, Frequenz doppelt, und wenn Entry-Route, Exit-Route oder Track in den Ring eines gegnerischen SAM reichen. Dafür zählen alle Luftabwehr-Stellungen der Mission und die Threats, die du unter <a href="./intel">Intel</a> von Hand angelegt hast.</p><h3 id="zeitplan" tabindex="-1">Zeitplan <a class="header-anchor" href="#zeitplan" aria-label="Permalink to &quot;Zeitplan&quot;">​</a></h3><p><strong>On Track</strong> und <strong>Off Track</strong> sind dasselbe wie das Fenster des Tankers im <a href="./timing#tanker">Timing</a>: Änderst du es hier, ändert es sich dort, und umgekehrt. Fehlt noch eine H-Hour, schlägt Shardwing eine vor wie im Timing.</p><ul><li><strong>Off Track</strong> beendet den Orbit (in DCS eine Stop-Bedingung am Orbit). Danach fliegt die KI zum Ende des Legs und dann die Exit-Route.</li><li>Aus On Track und der Route bis zum Track rechnet Shardwing, wann die Gruppe starten muss. Bei einem Start am Boden zählen Anlassen und Rollen mit (die Minuten aus dem Timing). Ist sie zu früh oder zu spät am Track, legt <strong>Start auf … legen</strong> die Startzeit der Gruppe dorthin: Sie erscheint dann erst zu dieser Zeit, die Zeiten über ihren Wegpunkten wandern mit.</li><li>Liegt der nötige Start vor dem Missionsstart, steht da, wann der Track frühestens erreichbar ist.</li></ul><h3 id="ki-skript" tabindex="-1">KI-Skript <a class="header-anchor" href="#ki-skript" aria-label="Permalink to &quot;KI-Skript&quot;">​</a></h3><p>Ein kleines Skript ergänzt die Route in DCS. Der Schalter <strong>Beim Speichern einbauen</strong> gilt für die ganze Mission; ohne ihn fliegt die Gruppe so, wie es oben eingestellt ist.</p><ul><li><strong>Bingo</strong> (nur mit Track): Fällt der Sprit unter den Wert (Standard 30 %), beendet das Skript den Orbit. Die KI fliegt dann wie bei Off Track über das Ende des Legs die Exit-Route heim, statt auf direktem Weg quer durchs Gebiet.</li><li><strong>Ablösung:</strong> eine zweite Gruppe derselben Rolle, die den Track übernimmt. Kopiere dafür die Gruppe mit <strong>Duplizieren</strong> im Kopf (oder im Mission Editor; gleiche Route, gleicher Track) und wähle sie hier. Shardwing setzt bei ihr Late Activation und rechnet die Zeit aus, zu der sie starten muss, um vor Off Track am Track zu sein. Früher startet sie, wenn diese Gruppe unter <strong>Früher bei Sprit</strong> fällt oder (<strong>Bei Ausfall</strong>) abgeschossen wird oder landet. Bei der Ablösung selbst steht dann „Ablösung für …“, und <strong>Aktivierung auf … legen</strong> verschiebt ihre Zeit.</li></ul><p>Die Hinweise darunter melden Lücken, zum Beispiel eine Gruppe mit Late Activation, die nichts startet, oder eine Ablösung, die erst unter Bingo starten würde.</p><p>Die neuen Werte zeigen sich gleich überall: im Kopf des Flights, im <a href="./timing">Timing</a> beim Tankerfenster und auf den Kneeboards. Im <a href="./kneeboards#comm-plan">Comm Plan</a> schlägt <strong>Frequenzen vorschlagen</strong> für jeden Tanker und AWACS ohne eigenes Netz eines vor, benannt nach dem Callsign und mit dem TACAN im Zweck.</p><h2 id="die-anderen-reiter" tabindex="-1">Die anderen Reiter <a class="header-anchor" href="#die-anderen-reiter" aria-label="Permalink to &quot;Die anderen Reiter&quot;">​</a></h2>',58)),n("div",h,[n("a",c,[n("span",p,[i(t,{name:"bomb"})]),e[0]||(e[0]=n("span",{class:"tile-title"},"Beladung",-1)),e[1]||(e[1]=n("span",{class:"tile-text"},"Stationsleiste, Waffen, Fuel, Chaff/Flare, Gun.",-1))]),n("a",m,[n("span",b,[i(t,{name:"memory-stick"})]),e[2]||(e[2]=n("span",{class:"tile-title"},"DTC",-1)),e[3]||(e[3]=n("span",{class:"tile-text"},"Cartridges für F-16C und F/A-18C.",-1))]),n("a",k,[n("span",f,[i(t,{name:"crosshair"})]),e[4]||(e[4]=n("span",{class:"tile-title"},"Angriff",-1)),e[5]||(e[5]=n("span",{class:"tile-text"},"Pop-up, Toss, Standoff – vom Ziel aus gerechnet.",-1))]),n("a",S,[n("span",A,[i(t,{name:"clipboard-list"})]),e[6]||(e[6]=n("span",{class:"tile-title"},"Lineup Card",-1)),e[7]||(e[7]=n("span",{class:"tile-text"},"Die Kneeboard-Seiten des Flights.",-1))])])])}const R=a(g,[["render",z]]);export{M as __pageData,R as default};
